const q = ($json.searchQuery || $json.query || '').toString().trim();
const lc = q.toLowerCase();
const countries = ['India','United States','USA','UK','United Kingdom','Canada','Germany','Australia','Singapore'];
let country = '';
const explicitCountry = ($json.country || $json.location || '').toString().trim();
if (explicitCountry) {
  const ec = explicitCountry.toLowerCase();
  if (ec === 'usa') { country = 'United States'; }
  else if (ec === 'uk') { country = 'United Kingdom'; }
  else { country = explicitCountry; }
}
if (!country) {
  for (const c of countries) {
    if (lc.includes(c.toLowerCase())) {
      country = c === 'USA' ? 'United States' : c === 'UK' ? 'United Kingdom' : c;
      break;
    }
  }
}
const cities = ['Hyderabad','Bengaluru','Bangalore','Mumbai','New Delhi','Delhi','Pune','Chennai','Gurgaon','Gurugram','Noida','Kolkata','Jaipur','Lucknow','Ahmedabad','Indore','London','New York','San Francisco','Berlin','Toronto','Sydney','Singapore'];
let city = '';
for (const c of cities) { if (lc.includes(c.toLowerCase())) { city = c; break; } }
const location = city || country || '';
const businessModels = [
  { key: 'C2C', patterns: ['c2c','corp to corp','corp-to-corp','corporation to corporation','corporate to corporate'] },
  { key: 'B2B', patterns: ['b2b','business to business','business-to-business'] },
  { key: 'B2C', patterns: ['b2c','business to consumer','business-to-consumer'] },
  { key: 'C2B', patterns: ['c2b','consumer to business','consumer-to-business'] }
];
const detectedBusinessModels = [];
for (const model of businessModels) {
  const found = model.patterns.some(pattern => lc.includes(pattern));
  if (found) { detectedBusinessModels.push(model.key); }
}
let title = q;
for (const model of businessModels) {
  for (const pattern of model.patterns) {
    title = title.replace(new RegExp('\\b' + pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'ig'), ' ');
  }
}
title = title.replace(/\b\d+\s*(?:-|to)\s*\d+\s*years?\b/ig, ' ');
title = title.replace(/\b\d+\+?\s*years?\b/ig, ' ');
title = title.replace(/\bremote\b/ig, ' ');
title = title.replace(/\bhybrid\b/ig, ' ');
title = title.replace(/\bon[- ]?site\b/ig, ' ');
title = title.replace(/\bonsite\b/ig, ' ');
if (city) { title = title.replace(new RegExp(city.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'ig'), ' '); }
if (country) { title = title.replace(new RegExp(country.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'ig'), ' '); }
title = title.replace(/[,-]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
const technologies = ['react native','python','java','javascript','typescript','c++','c#','.net','dotnet','golang','go','rust','php','ruby','kotlin','swift','react','reactjs','angular','vue','nextjs','next.js','node','nodejs','express','appian','salesforce','servicenow','sap','oracle','aws','azure','gcp','docker','kubernetes','flutter','android','ios','tensorflow','pytorch','langchain','langgraph','power bi','tableau','spark','hadoop'];
const detectedTechnologies = [];
for (const tech of technologies) { if (lc.includes(tech.toLowerCase())) { detectedTechnologies.push(tech); } }
const keywords = [];
const pushKeyword = (value) => {
  if (!value) return;
  const cleaned = String(value).replace(/\s+/g, ' ').trim();
  if (!cleaned) return;
  const exists = keywords.some(x => x.toLowerCase() === cleaned.toLowerCase());
  if (!exists) { keywords.push(cleaned); }
};
pushKeyword(title);
const technology = detectedTechnologies.length ? detectedTechnologies[0] : '';
const titleLc = title.toLowerCase();
if (technology === 'python') {
  if (titleLc.includes('backend')) { pushKeyword('Python Backend Developer'); pushKeyword('Python Backend Engineer'); }
  else { pushKeyword('Python Developer'); pushKeyword('Python Backend Developer'); pushKeyword('Python Software Engineer'); }
}
else if (technology === 'appian') { pushKeyword('Appian Developer'); pushKeyword('Appian BPM Developer'); pushKeyword('Appian Engineer'); }
else if (technology === 'java') { pushKeyword('Java Developer'); pushKeyword('Java Backend Developer'); pushKeyword('Java Software Engineer'); }
else if (technology === 'javascript' || technology === 'typescript') { pushKeyword(technology + ' Developer'); pushKeyword(technology + ' Software Engineer'); }
else if (technology === '.net' || technology === 'dotnet') { pushKeyword('.NET Developer'); pushKeyword('.NET Backend Developer'); pushKeyword('.NET Software Engineer'); }
else if (technology === 'react native') { pushKeyword('React Native Developer'); pushKeyword('React Native Engineer'); pushKeyword('React Native Mobile Developer'); }
else if (technology === 'react' || technology === 'reactjs') { pushKeyword('React Developer'); pushKeyword('React Frontend Developer'); }
else if (technology === 'angular') { pushKeyword('Angular Developer'); pushKeyword('Angular Frontend Developer'); }
else if (technology === 'salesforce') { pushKeyword('Salesforce Developer'); pushKeyword('Salesforce Engineer'); }
else if (technology === 'servicenow') { pushKeyword('ServiceNow Developer'); pushKeyword('ServiceNow Engineer'); }
else { const words = title.split(/\s+/).filter(Boolean); if (words.length >= 2) { pushKeyword(words.slice(0, 2).join(' ')); } }
const genericOnly = ['developer','engineer','software engineer','software developer','backend engineer','backend developer','frontend engineer','frontend developer','programmer','sde'];
const filteredKeywords = keywords.filter(k => { const kl = k.toLowerCase().trim(); if (technology) { if (genericOnly.includes(kl)) { return false; } } return true; });
const buildQuery = (keyword) => {
  let query = keyword;
  if (detectedBusinessModels.length > 0) { query += ' ' + detectedBusinessModels.join(' '); }
  query += ' hiring';
  if (location) { query += ' ' + location; }
  return query.replace(/\s{2,}/g, ' ').trim();
};
let postSearchQueries = filteredKeywords.slice(0, 5).map(buildQuery);
if (postSearchQueries.length === 0) { postSearchQueries = [buildQuery(title)]; }
const searchQuery = buildQuery(title);
const naukari = title.replace(/\s{2,}/g, ' ').trim();
const dp = ($json.datePosted || '').toString().toLowerCase().trim();

let datePosted = 'any time';

if (
  dp.includes('past-24h') ||
  dp.includes('past 24 hours') ||
  dp.includes('past 24 hour') ||
  dp.includes('last 24 hours') ||
  dp.includes('last 24 hour') ||
  dp === '24h'
) {
  datePosted = 'past-24h';
}
else if (
  dp.includes('past-hour') ||
  dp.includes('past hour') ||
  dp.includes('last hour') ||
  dp === '1h'
) {
  datePosted = 'past-hour';
}
else if (
  dp.includes('past-week') ||
  dp.includes('past week') ||
  dp.includes('last week') ||
  dp === '7d'
) {
  datePosted = 'past-week';
}
else if (
  dp.includes('past-month') ||
  dp.includes('past month') ||
  dp.includes('last month') ||
  dp === '30d'
) {
  datePosted = 'past-month';
}
return [{ json: { rawQuery: q, jobTitle: title, searchQuery, postSearchQueries, keywords: filteredKeywords, naukari, location, country, detectedTechnologies, detectedBusinessModels, datePosted, specializationLocked: detectedTechnologies.length > 0, businessModelLocked: detectedBusinessModels.length > 0 } }];

const gen = $('Generate Post Search Query').first().json;
const rawQuery = gen.rawQuery || '';
const requestedJobTitle = gen.jobTitle || '';
const location = gen.location || '';
const lc = (s) => s == null ? '' : String(s).toLowerCase();
const cleanUrl = (u) => { if (!u) return ''; return String(u).replace(/^\[|\]$/g, '').replace(/\\_/g, '_').replace(/\\&/g, '&').trim(); };
const cleanText = (s) => { if (!s) return ''; return String(s).replace(/\r/g, '').replace(/\n+/g, '\n').trim(); };
const posts = $input.all().map(i => i.json).filter(p => p && typeof p === 'object' && Object.keys(p).length > 0);
const output = [];
const hiringWords = ['hiring','we are hiring',"we're hiring",'now hiring','looking for','join our team','open position','open role','job opening','vacancy','recruiting','recruit','recruiter','recruiters','apply','referral','referrals','career opportunity','job opportunity','hiring alert','job alert','immediate opening','opportunity'];
const businessModelWords = ['c2c','corp2corp','corp to corp','corp-to-corp','contract','contractor','contract jobs','contract role','contract roles','consultant','consultants','consulting','hotlist','bench','bench sales','available consultant','available consultants','resources available','it resources','vendor','vendors','distribution list','distribution','client'];
const rawQueryWords = lc(rawQuery).split(/[^a-z0-9+#.-]+/).filter(word => word.length > 2);
const ignoredWords = new Set(['the','and','for','with','from','job','jobs','need','needed','hiring','opening','open','role']);
const queryKeywords = rawQueryWords.filter(word => !ignoredWords.has(word));
for (const p of posts) {
  const postUrl = cleanUrl(p.post_url || p.postUrl || p.url || '');
  const postContent = cleanText(p.text || p.content || p.postText || '');
  const author = p.author || {};
  const authorName = cleanText(author.name || p.authorName || '');
  const authorProfileUrl = cleanUrl(author.profile_url || p.authorProfileUrl || p.profileUrl || '');
  const postedAt = author.posted_at || {};
  const postPublishedAt = postedAt.date || postedAt.display_text || p.postedAt || p.date || '';
  const postTimestamp = postedAt.timestamp || '';
  const authorHeadline = cleanText(author.headline || '');
  const authorProfileId = author.profile_id || '';
  const contentLc = lc(postContent);
  const matchedQueryKeywords = queryKeywords.filter(keyword => contentLc.includes(keyword));
  const matchedHiringWords = hiringWords.filter(word => contentLc.includes(lc(word)));
  const hasHiringSignal = matchedHiringWords.length > 0;
  const matchedBusinessModelWords = businessModelWords.filter(word => contentLc.includes(lc(word)));
  const hasBusinessModelSignal = matchedBusinessModelWords.length > 0;
  const titleWords = lc(requestedJobTitle).split(/[^a-z0-9+#.-]+/).filter(word => word.length > 2);
  const matchedTitleWords = titleWords.filter(word => contentLc.includes(word));
  const hasJobTitleMatch = matchedTitleWords.length > 0;
  const locationLc = lc(location);
  const locationMatch = !!locationLc && contentLc.includes(locationLc);
  let score = 0;
  const signals = [];
  if (hasHiringSignal) { score += 2; signals.push('hiring_language'); }
  if (hasBusinessModelSignal) { score += 2; signals.push('business_model_language'); }
  if (matchedQueryKeywords.length > 0) { score += Math.min(matchedQueryKeywords.length, 4); signals.push('raw_query_match'); }
  if (hasJobTitleMatch) { score += 2; signals.push('job_title_match'); }
  if (locationMatch) { score += 1; signals.push('location_match'); }
  const queryHasC2C = lc(rawQuery).includes('c2c') || lc(rawQuery).includes('corp2corp') || lc(rawQuery).includes('corp to corp');
  const relevantForC2C = queryHasC2C && hasBusinessModelSignal && (matchedQueryKeywords.length > 0 || hasJobTitleMatch);
  const relevantNormal = !queryHasC2C && hasHiringSignal && (matchedQueryKeywords.length > 0 || hasJobTitleMatch);
  const relevant = relevantForC2C || relevantNormal;
  if (!relevant) { continue; }
  const profileLc = lc(authorProfileUrl);
  let postAuthorType = 'unknown';
  if (profileLc.includes('/in/') || profileLc.includes('/pub/')) { postAuthorType = 'individual'; }
  else if (profileLc.includes('/company/')) { postAuthorType = 'company'; }
  else if (authorName) { postAuthorType = 'individual'; }
  let posterProfileStatus = 'not_found';
  if (authorProfileUrl && (profileLc.includes('/in/') || profileLc.includes('/pub/'))) { posterProfileStatus = 'confirmed'; }
  else if (authorName) { posterProfileStatus = 'candidate'; }
  const postValid = !!postUrl && !!postContent && !!authorName;
  output.push({ json: {
    source: 'linkedin',
    rawQuery,
    jobTitle: requestedJobTitle || rawQuery,
    location,
    postUrl,
    postContent,
    postPublishedAt,
    postTimestamp,
    postAuthorName: authorName,
    postAuthorProfileUrl: authorProfileUrl,
    postAuthorHeadline: authorHeadline,
    postAuthorProfileId: authorProfileId,
    postAuthorType,
    posterProfileStatus,
    posterValid: posterProfileStatus === 'confirmed',
    matchScore: score,
    matchSignals: signals,
    keywordsMatched: matchedQueryKeywords,
    hiringSignalsMatched: matchedHiringWords,
    businessModelSignalsMatched: matchedBusinessModelWords,
    postValid,
    research_status: 'pending_agent_reach'
  } });
}
return output;

const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const posterUrl = j.poster_linkedin_url || (j.poster && j.poster.linkedinUrl) || '';
  const postUrl = j.post_url || (j.post && j.post.url) || '';
  const key = posterUrl || postUrl;
  if (!key) { out.push(it); continue; }
  if (seen.has(key)) continue;
  seen.add(key);
  out.push(it);
}
return out;

const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const post = j.post || {};
  const poster = j.poster || {};
  const company = j.company || {};
  const contact = j.contact || {};
  const research = j.research || {};
  const joinArr = (a) => Array.isArray(a) ? a.join(', ') : (a || '');
  out.push({ json: {
    'Job Title': j.rawQuery || '',
    'Company': company.name || '',
    'Company URL': company.linkedinUrl || '',
    'Job URL': '',
    'Job Location': '',
    'Job Description': '',
    'Post URL': post.url || j.post_url || '',
    'Posted At': post.publishedAt || '',
    'Poster Name': poster.name || j.poster_name || '',
    'Poster LinkedIn URL': poster.linkedinUrl || j.poster_linkedin_url || '',
    'Poster Profile Status': poster.profileStatus || '',
    'Post Content': post.content || '',
    'Person Role': research.role || '',
    'Emails': joinArr(contact.emails),
    'Phone Numbers': joinArr(contact.phoneNumbers),
    'Confidence': research.confidence != null ? research.confidence : 0,
    'Research Status': research.status || j.research_status || '',
    'Backend Used': research.backend || '',
    'Scraped At': new Date().toISOString()
  } });
}
return out;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const row = { ...($('Prepare Sheet Rows').all()[i] ? $('Prepare Sheet Rows').all()[i].json : {}) };
  const raw = items[i].json || {};
  const ext = raw.output || raw;
  const pick = (v) => (v == null ? '' : String(v).trim());
  const company = pick(ext.companyName);
  const jobTitle = pick(ext.jobTitle);
  const jobLocation = pick(ext.jobLocation);
  const jobDescription = pick(ext.jobDescription);
  const jobUrl = pick(ext.jobUrl);
  const personRole = pick(ext.personRole);
  const emails = pick(ext.emails);
  const phones = pick(ext.phoneNumbers);
  if (company) row['Company'] = company;
  if (jobTitle) row['Job Title'] = jobTitle;
  if (jobLocation) row['Job Location'] = jobLocation;
  if (jobDescription) row['Job Description'] = jobDescription;
  if (jobUrl) row['Job URL'] = jobUrl;
  if (personRole) row['Person Role'] = personRole;
  if (emails && !row['Emails']) row['Emails'] = emails;
  if (phones && !row['Phone Numbers']) row['Phone Numbers'] = phones;
  out.push({ json: row });
}
return out;

const r = $json || {};
const ctx = $('Loop Over Posts').item.json;
const nm = (r.name || '').toString().toLowerCase().trim();
let research_status = r.research_status || 'research_failed';
let confidence = typeof r.confidence === 'number' ? r.confidence : (parseFloat(r.confidence) || 0);
let name = r.name || '';
let role = r.role || '';
let company = r.company || ctx.companyName || '';
let emails = Array.isArray(r.emails) ? r.emails : [];
let phones = Array.isArray(r.phone_numbers) ? r.phone_numbers : [];
let linkedin_url = r.linkedin_url || ctx.postAuthorProfileUrl || '';
const contaminated = nm.includes('join linkedin') || nm.includes('sign up') || nm.includes('log in') || nm.includes('login') || nm === 'linkedin';
if (contaminated) { research_status = 'linkedin_profile_inaccessible'; confidence = 0; name = ''; role = ''; emails = []; phones = []; }
emails = emails.filter(e => typeof e === 'string' && e.includes('@'));
phones = phones.filter(p => p != null && String(p).trim() !== '');
if (emails.length === 0 && Array.isArray(ctx.emails)) { emails = ctx.emails.filter(e => typeof e === 'string' && e.includes('@')); }
if (phones.length === 0 && Array.isArray(ctx.phoneNumbers)) { phones = ctx.phoneNumbers.filter(p => p != null && String(p).trim() !== ''); }
const lead = {
  source: 'linkedin',
  rawQuery: ctx.rawQuery || '',
  post: { url: ctx.postUrl || '', content: ctx.postContent || '', publishedAt: ctx.postPublishedAt || '' },
  poster: { name: name || ctx.postAuthorName || '', linkedinUrl: linkedin_url, profileStatus: ctx.posterProfileStatus || '' },
  company: { name: company, linkedinUrl: ctx.companyUrl || '' },
  contact: { emails: emails, phoneNumbers: phones },
  research: { confidence: confidence, status: research_status, backend: r.backend_used || '', role: role },
  post_url: ctx.postUrl || '',
  poster_linkedin_url: linkedin_url,
  poster_name: name || ctx.postAuthorName || '',
  research_status: research_status,
  match_score: ctx.matchScore || 0,
  match_signals: Array.isArray(ctx.matchSignals) ? ctx.matchSignals : []
};
return [{ json: lead }];

const c = $json || {};
const hasUrl = !!c.postAuthorProfileUrl;
const status = hasUrl ? 'poster_not_researched' : 'poster_profile_missing';
return [{ json: {
  source: 'linkedin',
  rawQuery: c.rawQuery || '',
  post: { url: c.postUrl || '', content: c.postContent || '', publishedAt: c.postPublishedAt || '' },
  poster: { name: c.postAuthorName || '', linkedinUrl: c.postAuthorProfileUrl || '', profileStatus: c.posterProfileStatus || 'not_found' },
  company: { name: c.companyName || '', linkedinUrl: c.companyUrl || '' },
  contact: { emails: Array.isArray(c.emails) ? c.emails : [], phoneNumbers: Array.isArray(c.phoneNumbers) ? c.phoneNumbers : [] },
  research: { confidence: (typeof c.confidence === 'number' ? c.confidence : 0), status: status, backend: '', role: '' },
  post_url: c.postUrl || '',
  poster_linkedin_url: c.postAuthorProfileUrl || '',
  poster_name: c.postAuthorName || '',
  research_status: status,
  match_score: c.matchScore || 0,
  match_signals: Array.isArray(c.matchSignals) ? c.matchSignals : []
} }];

// Flatten the webhook body so downstream nodes read the same fields as the form/execute triggers.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
return [{ json: {
  searchQuery: str(body.searchQuery),
  datePosted: str(body.datePosted),
  location: str(body.location),
  maxPosts: body.maxPosts
} }];
